import{_ as a,o as l,c as o,ag as t}from"./chunks/framework.CtWPcAmt.js";const g=JSON.parse('{"title":"第 21 章：内容创作与研究案例——从「一堆经验」到「一套教程」","description":"用本书项目的真实过程演示内容策划与研究类任务：选题、素材盘点、框架设计、可信度管理、长文协作。","frontmatter":{"title":"第 21 章：内容创作与研究案例——从「一堆经验」到「一套教程」","description":"用本书项目的真实过程演示内容策划与研究类任务：选题、素材盘点、框架设计、可信度管理、长文协作。","layout":"doc","lastUpdated":true},"headers":[],"relativePath":"guide/21-content-research-case.md","filePath":"guide/21-content-research-case.md","lastUpdated":null}'),i={name:"guide/21-content-research-case.md"};function r(n,e,s,d,c,h){return l(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="第-21-章-内容创作与研究案例——从「一堆经验」到「一套教程」" tabindex="-1">第 21 章：内容创作与研究案例——从「一堆经验」到「一套教程」 <a class="header-anchor" href="#第-21-章-内容创作与研究案例——从「一堆经验」到「一套教程」" aria-label="Permalink to &quot;第 21 章：内容创作与研究案例——从「一堆经验」到「一套教程」&quot;">​</a></h1><h2 id="案例摘要" tabindex="-1">案例摘要 <a class="header-anchor" href="#案例摘要" aria-label="Permalink to &quot;案例摘要&quot;">​</a></h2><ul><li>使用场景：内容创作与研究</li><li>使用者基础：能完成第 1–14 章学习即可复现</li><li>使用的 Agent：桌面 Agent + 视觉模型辅助（第 5 章界面讲解文档的素材流程）</li><li>完成时间：跨周迭代（本书项目本身）</li><li>风险等级：低—中（事实可信度管理是重点）</li><li>最终交付物：23 章教程框架 + 各章正文（含你正在读的这一章）</li></ul><h2 id="任务背景" tabindex="-1">任务背景 <a class="header-anchor" href="#任务背景" aria-label="Permalink to &quot;任务背景&quot;">​</a></h2><p>作者有多款 AI 产品的真实使用经验，想写成一套面向零基础读者的教程。初始问题：经验散落在十几个文档、截图、聊天记录里，不成体系；市面上资料要么是产品说明书，要么是「参数党」评测，缺少「教人怎么用」的实践教程。</p><h2 id="原始需求" tabindex="-1">原始需求 <a class="header-anchor" href="#原始需求" aria-label="Permalink to &quot;原始需求&quot;">​</a></h2><blockquote><p>「我想写一套 AI Agent 教程，把我用这些产品的经验整理出来，教普通人怎么选、怎么用。」</p></blockquote><p>（模糊版：没定读者、没定范围、没定结构——如果直接让 Agent「帮我写教程」，会得到一篇四不像。）</p><h2 id="任务判断" tabindex="-1">任务判断 <a class="header-anchor" href="#任务判断" aria-label="Permalink to &quot;任务判断&quot;">​</a></h2><ul><li>为什么适合 Agent：素材整理、框架梳理、长文起草、格式统一；</li><li>交给 Agent：素材盘点、目录草案、各章起草、术语统一、易变信息核验辅助；</li><li>人必须做的：定读者与边界（零基础、只讲桌面版）、定框架（23 章六篇）、做事实分级（官方事实/实测/推断）、下写作结论。</li></ul><h2 id="整理后的任务卡-框架设计阶段" tabindex="-1">整理后的任务卡（框架设计阶段） <a class="header-anchor" href="#整理后的任务卡-框架设计阶段" aria-label="Permalink to &quot;整理后的任务卡（框架设计阶段）&quot;">​</a></h2><ul><li><strong>目标</strong>：产出教程的完整目录框架与写作规范；</li><li><strong>上下文</strong>：面向零基础读者；只讲桌面 GUI 版；Qoder/TraeWork/ZCode 只用中国版；</li><li><strong>输入材料</strong>：作者经验笔记（多份文档）；</li><li><strong>范围与约束</strong>：不把作者个案写成普遍规律（如 Claude 封号）；易变信息标注核验日期；不虚构引用；</li><li><strong>交付物</strong>：23 章目录（<code>docs/01-book-outline.md</code>）、编辑规范（<code>docs/03</code>）、内容清单（<code>docs/04</code>）；</li><li><strong>验收标准</strong>：目录覆盖「认识→选型→任务→工作流→Harness→案例」六篇；每章有明确产出；规范含术语与事实分级要求。</li></ul><h2 id="执行过程" tabindex="-1">执行过程 <a class="header-anchor" href="#执行过程" aria-label="Permalink to &quot;执行过程&quot;">​</a></h2><ol><li><strong>盘点</strong>：把经验文档集中到项目目录，用 Agent 帮助提取「可用素材」；</li><li><strong>定框架</strong>：人先定六篇叙事线（第 5 篇内容策略），Agent 协助扩展为 23 章；</li><li><strong>定规范</strong>：把写作纪律写成 <code>docs/03</code> 编辑规范（先结论、术语白话、事实分级）；</li><li><strong>逐章起草</strong>：用章节模板（<code>templates/chapter-template.md</code>）逐章生成——你正在读的每一章都来自这个流程；</li><li><strong>易变信息集中管理</strong>：价格/福利统一放 <code>docs/07</code>，各章引用而非复制。</li></ol><h2 id="出现的问题" tabindex="-1">出现的问题 <a class="header-anchor" href="#出现的问题" aria-label="Permalink to &quot;出现的问题&quot;">​</a></h2><ul><li><strong>幻觉风险</strong>：Agent 起草时出现过「编造价格」「虚构来源」——靠第 10 章事实核查拦截；</li><li><strong>范围漂移</strong>：初版目录加入了「命令行」「模型原理」内容，违反「零基础、GUI」边界——人修正边界；</li><li><strong>事实分级混淆</strong>：作者封号经历差点被写成「该产品容易封号」——规范要求写成个案；</li><li><strong>版本过期</strong>：QoderWork 学生福利已截止仍被当新福利——<code>docs/07</code> 核验清单拦截。</li></ul><h2 id="修正与判断" tabindex="-1">修正与判断 <a class="header-anchor" href="#修正与判断" aria-label="Permalink to &quot;修正与判断&quot;">​</a></h2><ul><li>建立「三色事实标注」：官方事实 / 实测结果 / 作者推断，写入 <code>docs/03</code> 并要求每章附录 C 自查；</li><li>目录砍掉 CLI 与模型原理内容，移入「选读附录」；</li><li>所有价格标注核验日期，活动截止的只作历史信息；</li><li>用统一章节模板保证 20+ 章结构一致（第 12 章模板库的价值）。</li></ul><h2 id="最终结果与验收" tabindex="-1">最终结果与验收 <a class="header-anchor" href="#最终结果与验收" aria-label="Permalink to &quot;最终结果与验收&quot;">​</a></h2><ul><li>产出：23 章框架 + 编辑规范 + 内容清单 + 第 5、6 章完整正文 + 其余章节正文；</li><li>验收：每章过「模板结构」「术语白话」「事实分级」三项检查；链接批量校验（第 18 章回归验证的实践）；</li><li>持续迭代：内容清单（<code>docs/04</code>）打勾管理进度，易变信息定期复核。</li></ul><h2 id="复盘" tabindex="-1">复盘 <a class="header-anchor" href="#复盘" aria-label="Permalink to &quot;复盘&quot;">​</a></h2><ul><li>Agent 做得好的：结构扩展、逐章起草、格式统一、批量校验；</li><li>人必须介入的：边界与口径、事实分级、最终结论；</li><li>可沉淀：章节模板（<code>templates/chapter-template.md</code>）、编辑规范（<code>docs/03</code>）、易变信息表机制（<code>docs/07</code>）——<strong>内容创作类任务的完整方法论</strong>。</li></ul><h2 id="给新手的最小版本" tabindex="-1">给新手的最小版本 <a class="header-anchor" href="#给新手的最小版本" aria-label="Permalink to &quot;给新手的最小版本&quot;">​</a></h2><p>30 分钟复现：选一个你熟悉的话题（如「如何挑选跑步鞋」）→ 写三条写作纪律（如「价格标日期」「不写没验证的数据」）→ 用任务卡让 Agent 起草一篇带模板结构的短文 → 按纪律验收。<strong>内容创作的核心不是「让 AI 写」，而是「定边界、给模板、管事实」。</strong></p>',24)])])}const m=a(i,[["render",r]]);export{g as __pageData,m as default};
